                      <li><kbd><i class="fas fa-arrow-up"></i></kbd> ${C("tooltips.stackKeyboardShortcuts.moveItemUpInStack")}</li>
                      <li><kbd><i class="fas fa-arrow-down"></i></kbd> ${C("tooltips.stackKeyboardShortcuts.moveItemDownInStack")}</li>
                      <li><kbd>R</kbd> ${C("tooltips.stackKeyboardShortcuts.removeCurrentFromStack")}</li>
